const { Server } = require('@modelcontextprotocol/sdk/server/index.js');
const { StdioServerTransport } = require('@modelcontextprotocol/sdk/server/stdio.js');
const { ListToolsRequestSchema, CallToolRequestSchema } = require('@modelcontextprotocol/sdk/types.js');
const { openPrograms } = require('./program-store.cjs');
const actor = process.argv[2], store = openPrograms(process.env.SCIENCEEVOLVE_ALPHA_SCIENCE_ROOT, actor);
const definitions = [
  { name: 'get_search_state', description: 'Read actual candidate queue, baseline/evaluator receipts, scores, statuses and methodReadiness per worker. Missing, pending, and scientific negative results are distinct.', inputSchema: { type: 'object', properties: {}, additionalProperties: false } },
  { name: 'inspect_candidate', description: 'Read one actual async evaluation status, cascade results, metrics and errors; no guessed results.', inputSchema: { type: 'object', required: ['candidateId'], properties: { candidateId: { type: 'string' } }, additionalProperties: false } }
];
if (['worker_a','worker_b'].includes(actor)) definitions.push(
  { name: 'sample_prompt', description: 'Sample a current database parent, distinct inspirations and your actual failure feedback. Uses per-island elites/diversity and live scored results; keep the returned promptId.', inputSchema: { type: 'object', required: ['requestId'], properties: { requestId: { type: 'string' } }, additionalProperties: false } },
  { name: 'submit_diff', description: 'Apply actual SEARCH/REPLACE diff inside EVOLVE-BLOCK, enqueue without a generation barrier, preserve parent/inspiration provenance. Final candidate at this three-candidate scale requires a new sampled prompt containing actual completed earlier own feedback. Stable request IDs protect against duplicates.', inputSchema: { type: 'object', required: ['requestId','promptId','diff'], properties: { requestId: { type: 'string' }, promptId: { type: 'string' }, diff: { type: 'string', maxLength: 100000 } }, additionalProperties: false } }
);
if (['worker_a','worker_b','audit'].includes(actor)) definitions.push({ name: 'export_search_artifacts', description: 'Write actual candidate programs/diffs, final metric/error receipts and database state to your own results/<role> branch path. Does not commit or finish task.', inputSchema: { type: 'object', properties: {}, additionalProperties: false } });
const server = new Server({ name: 'alphaevolve-task-tools', version: '0.1.0' }, { capabilities: { tools: {} } });
server.setRequestHandler(ListToolsRequestSchema, async () => ({ tools: definitions }));
server.setRequestHandler(CallToolRequestSchema, async request => {
  const { name, arguments: args = {} } = request.params;
  if (!definitions.some(tool => tool.name === name)) throw new Error('Tool not assigned to this role');
  try { return { content: [{ type: 'text', text: JSON.stringify(await store.operations[name](args)) }] }; }
  catch (error) { return { isError: true, content: [{ type: 'text', text: error.message }] }; }
});
server.connect(new StdioServerTransport()); process.stdin.on('end', () => { store.close(); server.close().finally(() => process.exit()); });

