const fs = require('node:fs');
const path = require('node:path');
const { createHash } = require('node:crypto');
const { DatabaseSync } = require('node:sqlite');
const hash = value => createHash('sha256').update(typeof value === 'string' || Buffer.isBuffer(value) ? value : JSON.stringify(value)).digest('hex');
const idOk = id => typeof id === 'string' && /^[a-zA-Z0-9_-]{1,100}$/.test(id);
const timestamp = () => new Date().toISOString();
function applyDiff(program, diff) {
  const edits = [...diff.matchAll(/<<<<<<< SEARCH\r?\n([\s\S]*?)\r?\n=======\r?\n([\s\S]*?)\r?\n>>>>>>> REPLACE/g)];
  if (!edits.length) throw new Error('Supply SEARCH/REPLACE edits, not an unrelated full program');
  let result = program;
  for (const edit of edits) {
    const search = edit[1], replace = edit[2];
    if (!search || result.split(search).length !== 2) throw new Error('Each SEARCH block must match exactly once');
    result = result.replace(search, replace);
  }
  if (!result.includes('# EVOLVE-BLOCK-START') || !result.includes('# EVOLVE-BLOCK-END')) throw new Error('Evolution markers must be preserved');
  const outside = text => [text.split('# EVOLVE-BLOCK-START')[0], text.split('# EVOLVE-BLOCK-END').slice(1).join('# EVOLVE-BLOCK-END')];
  if (JSON.stringify(outside(result)) !== JSON.stringify(outside(program))) throw new Error('Edits outside the authorized evolution block are forbidden');
  return result;
}
function openPrograms(root, actor) {
  if (!path.isAbsolute(root) || !['worker_a', 'worker_b', 'manager', 'main', 'audit', 'evaluator'].includes(actor)) throw new Error('Known actor and explicit root required');
  const config = JSON.parse(fs.readFileSync(path.join(root, 'settings.json'), 'utf8'));
  if (config.method !== 'alphaevolve') throw new Error('Wrong method state');
  const db = new DatabaseSync(path.join(root, 'programs.sqlite'));
  db.exec('PRAGMA busy_timeout=5000');
  for(let attempt=0;;attempt++){
    try{
      if(db.prepare('PRAGMA journal_mode').get().journal_mode!=='wal')db.exec('PRAGMA journal_mode=WAL');
      db.exec('CREATE TABLE IF NOT EXISTS programs(id TEXT PRIMARY KEY, json TEXT NOT NULL); CREATE TABLE IF NOT EXISTS prompts(id TEXT PRIMARY KEY, json TEXT NOT NULL); CREATE TABLE IF NOT EXISTS journal(seq INTEGER PRIMARY KEY AUTOINCREMENT,json TEXT NOT NULL);');
      break;
    }catch(error){if(![5,6].includes(error.errcode)||attempt>=80){db.close();throw error;}Atomics.wait(new Int32Array(new SharedArrayBuffer(4)),0,0,25);}
  }
  const log = entry => db.prepare('INSERT INTO journal(json) VALUES (?)').run(JSON.stringify({ ...entry, at: timestamp() }));
  const list = () => db.prepare('SELECT json FROM programs').all().map(row => JSON.parse(row.json));
  const get = id => { const row = db.prepare('SELECT json FROM programs WHERE id=?').get(id); return row ? JSON.parse(row.json) : null; };
  const save = program => db.prepare('INSERT INTO programs(id,json) VALUES (?,?) ON CONFLICT(id) DO UPDATE SET json=excluded.json').run(program.id, JSON.stringify(program));
  const transaction = fn => { db.exec('BEGIN IMMEDIATE'); try { const result = fn(); db.exec('COMMIT'); return result; } catch (error) { db.exec('ROLLBACK'); throw error; } };
  const initialCode = fs.readFileSync(config.initialProgram, 'utf8');
  db.prepare('INSERT OR IGNORE INTO programs(id,json) VALUES (?,?)').run('initial', JSON.stringify({ id: 'initial', code: initialCode, codeSha256: hash(initialCode), actor: 'evaluator', island: 0, status: 'queued', requestedAt: timestamp(), seedProgram: true }));
  const final = program => ['scored','rejected'].includes(program.status);
  const feedbackContext = prompt => ({
    scoredParent: Boolean(prompt.parent?.metrics),
    scoredInspirations: prompt.inspirations?.map(program => program.id) ?? [],
    failureIds: prompt.failures?.map(program => program.id) ?? []
  });
  const readiness = () => {
    const programs = list();
    const prompts = db.prepare('SELECT json FROM prompts').all().map(row => JSON.parse(row.json));
    const workers = Object.fromEntries(['worker_a','worker_b'].map(name => {
      const owned = programs.filter(program => program.actor === name);
      const laterFeedback = prompts.filter(prompt => prompt.actor === name).filter(prompt => {
        const included = [prompt.parent?.metrics ? prompt.parent.id : null,...(prompt.inspirations??[]).map(item=>item.id),...(prompt.failures??[]).map(item=>item.id)].filter(Boolean);
        return owned.some(program => final(program) && program.finishedAt <= prompt.sampledAt && included.includes(program.id));
      }).map(prompt=>prompt.id);
      return [name,{created:owned.length,final:owned.filter(final).length,required:config.perWorkerBudget,laterOwnFeedbackPromptIds:laterFeedback,ready:owned.length===config.perWorkerBudget&&owned.every(final)&&laterFeedback.length>0}];
    }));
    return {workers,ready:Object.values(workers).every(worker=>worker.ready)&&final(programs.find(program=>program.id==='initial')),note:'Scientific evidence gate, not proof of native Git integration or model cognition. Final proposal must sample actual earlier own feedback at this reduced three-candidate scale; no generation-wide barrier.'};
  };
  const state = () => ({ method: config.method, publicTask: config.publicTask, perWorkerBudget: config.perWorkerBudget, evaluatorConcurrency: 2, programs: list().map(({ code, ...item }) => item), methodReadiness:readiness(), note: 'Independent public-method adaptation; unpublished original database parameters are not claimed.' });
  const worker = () => { if (!['worker_a', 'worker_b'].includes(actor)) throw new Error('Candidate creation is assigned only to independent generators'); };
  const operations = {
    get_search_state: async () => state(),
    sample_prompt: async args => {
      worker(); if (!idOk(args.requestId)) throw new Error('Stable requestId required');
      return transaction(() => {
        const id = `${actor}-${args.requestId}`;
        const retained = db.prepare('SELECT json FROM prompts WHERE id=?').get(id); if (retained) return JSON.parse(retained.json);
        const all = list(); if (all.filter(program => program.actor === actor).length >= config.perWorkerBudget) throw new Error('Authorized generation budget exhausted');
        const viable = all.filter(program => program.status === 'scored' && program.valid);
        const initial = all.find(program => program.id === 'initial');
        if (!viable.length && (!initial || ['queued','evaluating'].includes(initial.status))) throw new Error('Initial program must be actually evaluated before generation');
        const island = actor === 'worker_a' ? 0 : 1;
        const local = viable.filter(program => program.island === island); const population = local.length ? local : viable.length ? viable : [initial];
        // Transparent MAP-Elites-style archive: best in code-size bins on each island.
        // These descriptor bins/sampling weights are independent choices, not unpublished AlphaEvolve defaults.
        const archive = new Map();
        const score = program => program.metrics?.sum_of_radii ?? -Infinity;
        for (const program of population) { const bin = Math.floor(program.code.length / 1000); if (!archive.has(bin) || score(archive.get(bin)) < score(program)) archive.set(bin, program); }
        const elites = [...archive.values()].sort((a, b) => score(b) - score(a));
        const seed = parseInt(hash(id).slice(0, 8), 16);
        const parent = seed % 4 === 0 ? elites[seed % elites.length] : elites[0];
        const inspirations = viable.filter(program => program.id !== parent.id).sort((a,b) => b.metrics.sum_of_radii - a.metrics.sum_of_radii).slice(0, 2);
        const failures = all.filter(program => (program.actor === actor || program.seedProgram) && program.status === 'rejected').slice(-2).map(({ id, stages, error }) => ({ id, stages, error }));
        const prompt = { id, actor, island, parent: { id: parent.id, code: parent.code, metrics: parent.metrics }, inspirations: inspirations.map(({ id, code, metrics, island }) => ({ id, code, metrics, island })), failures, databaseRevision: all.length, instructions: config.taskInstructions, policy: 'size-bin elites within actor island; 75% best / 25% deterministic diverse sampling; global inspiration exchange. Explicit independent implementation choices.', sampledAt: timestamp() };
        prompt.feedbackContext = feedbackContext(prompt);
        db.prepare('INSERT INTO prompts(id,json) VALUES (?,?)').run(id, JSON.stringify(prompt)); log({ type: 'prompt.sampled', promptId: id, actor, parent: parent.id, inspirationIds: inspirations.map(program => program.id), revision: all.length }); return prompt;
      });
    },
    submit_diff: async args => {
      worker(); if (!idOk(args.requestId) || typeof args.diff !== 'string' || args.diff.length > 100000) throw new Error('Stable request id and bounded actual diff required');
      return transaction(() => {
        const id = `${actor}-${args.requestId}`, retained = get(id), requestHash = hash(args);
        if (retained) { if (retained.requestHash !== requestHash) throw new Error('Idempotency key cannot be changed'); return { candidateId: id, status: retained.status }; }
        const promptRow = db.prepare('SELECT json FROM prompts WHERE id=?').get(args.promptId);
        const prompt = promptRow && JSON.parse(promptRow.json); if (!prompt || prompt.actor !== actor) throw new Error('Use your actual sampled parent and inspirations');
        const all = list(); if (all.filter(program => program.actor === actor).length >= config.perWorkerBudget) throw new Error('Authorized generation budget exhausted');
        if (all.filter(program=>program.actor===actor).length===config.perWorkerBudget-1) {
          const included=[prompt.parent?.metrics?prompt.parent.id:null,...prompt.inspirations.map(item=>item.id),...prompt.failures.map(item=>item.id)].filter(Boolean);
          if (!all.some(program=>program.actor===actor&&final(program)&&program.finishedAt<=prompt.sampledAt&&included.includes(program.id))) throw new Error('Before the final candidate, inspect an actual completed earlier own evaluation, then sample_prompt with a NEW requestId so scored parent/inspiration or rejection feedback is included. Keep the other branch asynchronous; no whole-generation barrier.');
        }
        const code = applyDiff(prompt.parent.code, args.diff);
        const program = { id, actor, island: prompt.island, code, codeSha256: hash(code), diff: args.diff, parentId: prompt.parent.id, inspirationIds: prompt.inspirations.map(program => program.id), promptId: args.promptId, requestHash, status: 'queued', requestedAt: timestamp() };
        save(program); log({ type: 'candidate.queued', id, actor, parentId: program.parentId, codeSha256: program.codeSha256 });
        return { candidateId: id, status: 'queued', instruction: 'Evaluation runs asynchronously in the external atomic Task backend; do not wait on a group-wide barrier. You may sample/generate another candidate while this is pending, then poll its actual result.' };
      });
    },
    inspect_candidate: async ({ candidateId }) => {
      const program = get(candidateId); if (!program) throw new Error('Unknown candidate');
      const { code, diff, ...record } = program; return record;
    },
    export_search_artifacts: async () => {
      if (!['worker_a', 'worker_b', 'audit'].includes(actor)) throw new Error('Export belongs to business roles');
      const owned = list().filter(program => actor === 'audit' || program.actor === actor);
      if (owned.some(program => ['queued','evaluating'].includes(program.status))) throw new Error('Actual evaluations are still pending; preserve them, do not claim completion');
      const contract=readiness();
      if (actor==='audit'?!contract.ready:!contract.workers[actor].ready) throw new Error('Scientific evidence is incomplete: read get_search_state.methodReadiness; each generator needs three final receipts and a later sample containing its actual earlier feedback. Git integration remains a separate native requirement.');
      const directory = path.join(process.cwd(), 'results', actor); fs.mkdirSync(directory, { recursive: true });
      for (const program of owned) { fs.writeFileSync(path.join(directory, `${program.id}.py`), program.code); fs.writeFileSync(path.join(directory, `${program.id}.json`), JSON.stringify(program, null, 2)); }
      const prompts=db.prepare('SELECT json FROM prompts').all().map(row=>JSON.parse(row.json)).filter(prompt=>actor==='audit'||prompt.actor===actor);
      const journal=db.prepare('SELECT json FROM journal ORDER BY seq').all().map(row=>JSON.parse(row.json)).filter(entry=>actor==='audit'||entry.actor===actor||owned.some(program=>program.id===entry.id));
      fs.writeFileSync(path.join(directory,'prompts.json'),JSON.stringify(prompts,null,2));
      fs.writeFileSync(path.join(directory,'journal.json'),JSON.stringify(journal,null,2));
      fs.writeFileSync(path.join(directory, 'search-state.json'), JSON.stringify(state(), null, 2));
      return { relativePath: `results/${actor}`, candidates: owned.map(program => ({ id: program.id, status: program.status, valid: program.valid, metrics: program.metrics })) };
    }
  };
  return { operations, config, list, get, state, journal: () => db.prepare('SELECT json FROM journal ORDER BY seq').all().map(row => JSON.parse(row.json)),
    claimQueued: () => transaction(() => { const item = list().find(program => program.status === 'queued'); if (!item) return null; item.status = 'evaluating'; item.startedAt = timestamp(); save(item); log({ type: 'evaluation.started', id: item.id }); return item; }),
    finish: (id, receipt) => transaction(() => { const item = get(id); if (!item || item.status !== 'evaluating') throw new Error('Evaluation is not in the retained executing state'); Object.assign(item, receipt, { finishedAt: timestamp() }); save(item); log({ type: 'evaluation.finished', id, status: item.status, metrics: item.metrics, stageCount: item.stages?.length }); }),
    close: () => db.close() };
}
module.exports = { openPrograms, applyDiff, hash };

